package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** Periods by sheet, earliest first. */
@Repository
public class PeriodRepository {

    private static final RowMapper<Period> ROW = (rs, i) -> new Period(rs.getString("sheet_id"),
            rs.getString("name"), rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class),
            rs.getBoolean("closed"), rs.getBigDecimal("closed_total"));

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Period> list(String sheetId) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
    }

    /** Lock the sheet's row until the transaction ends, so concurrent period adds are checked one after the other. */
    public void lockSheet(String sheetId) {
        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", rs -> null, sheetId);
    }

    public Period insert(String sheetId, String name, LocalDate from, LocalDate to) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                sheetId, name, Date.valueOf(from), Date.valueOf(to));
        return new Period(sheetId, name, from, to, false, null);
    }

    /** The period on the sheet with this name (without regard to case or surrounding spaces), or null. */
    public Period find(String sheetId, String name) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name_key = LOWER(TRIM(?))", ROW, sheetId, name)
                .stream().findFirst().orElse(null);
    }

    /** The closed period on the sheet whose dates contain the date, or null when none does. */
    public Period closedOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.closed() && p.contains(date)).findFirst().orElse(null);
    }

    /** Close the period, fixing its due-total: false when it was already closed, and nothing is written. */
    public boolean close(Period period, BigDecimal total) {
        return jdbc.update("UPDATE period SET closed = TRUE, closed_total = ? WHERE sheet_id = ? AND name = ? AND NOT closed",
                total, period.sheetId(), period.name()) == 1;
    }

    /** Reopen the period, dropping its fixed due-total: false when it was not closed, and nothing is written. */
    public boolean reopen(Period period) {
        return jdbc.update("UPDATE period SET closed = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ? AND closed",
                period.sheetId(), period.name()) == 1;
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet's period: a name unique on the sheet and an inclusive from and to date; whether it is closed, and
 *  the due-total fixed when it was closed (null while open). */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal) {

    /** Whether this period shares a day with the dates from..to (inclusive). */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !this.from.isAfter(to) && !from.isAfter(this.to);
    }

    /** Whether the date falls in this period. */
    public boolean contains(LocalDate date) {
        return overlaps(date, date);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: the amount is required, a
 *  number with up to two decimals, below 0.00 only for a correction, which names (by a whole number) the claim it
 *  corrects, and only a correction names one; the date, when given, is a real yyyy-mm-dd date. */
public class ValidateClaim {
    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (amount.isEmpty()) {
            throw new InvalidClaimException("An amount is required.");
        }
        if (!amount.matches("-?\\d{1,12}(\\.\\d{1,2})?")) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
        Integer corrects = null;
        if (!rawCorrects.isEmpty()) {
            if (!rawCorrects.matches("\\d{1,9}")) {
                throw new InvalidClaimException("The claim corrected must be named by its number.");
            }
            corrects = Integer.valueOf(rawCorrects);
        }
        if (value.signum() < 0 && corrects == null) {
            throw new InvalidClaimException(
                    "A negative amount is a correction: name the number of the SETTLED claim it corrects.");
        }
        if (value.signum() >= 0 && corrects != null) {
            throw new InvalidClaimException("Only a correction (a negative amount) names a claim it corrects.");
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            if (!rawDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
                throw new InvalidClaimException("The date must be a date (yyyy-mm-dd).");
            }
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("The date must be a real date (yyyy-mm-dd).");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        if (note.length() > 1000) {
            throw new InvalidClaimException("A note is at most 1000 characters.");
        }
        body.set(new ClaimInput(request.user().trim(), value, date, note, corrects));
    }
}
package net.officefloor.hq.app.statement;

import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** How the sheet rounds a claim's live figures: by its policy date (the policy-date setting, else the sheet's today;
 *  null: none, everything rounds half to even), and the dates of its numbered claims (a correction rounds by the
 *  date of the claim it corrects). */
public record Rounding(LocalDate policy, Map<Integer, LocalDate> numbered) {

    /** The sheet's rounding as it is now. */
    public static Rounding of(String sheetId, SettingRepository settings, SheetRepository sheets,
            ClaimRepository claims) {
        LocalDate policy = settings.policyDate(sheetId);
        Map<Integer, LocalDate> numbered = new HashMap<>();
        for (Claim c : claims.list(sheetId)) {
            if (c.number() != null) {
                numbered.put(c.number(), c.date());
            }
        }
        return new Rounding(policy != null ? policy : sheets.today(sheetId), numbered);
    }

    /** Every figure rounded half to even. */
    public static Rounding none() {
        return new Rounding(null, Map.of());
    }

    /** How a claim's live figures round: half up when it (a correction: the claim it corrects) is dated before the
     *  policy date, else half to even. */
    public RoundingMode of(Claim claim) {
        LocalDate date = claim.corrects() != null ? numbered.getOrDefault(claim.corrects(), claim.date())
                : claim.date();
        return policy != null && date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}

